rules.query:
let rdp_events = SecurityEvent | where EventID == 4624 and LogonType == 10 | summarize rdp_time=min(TimeGenerated), rdp_src=any(SourceIP) by TargetUserName, Computer;
let cred_events = SecurityEvent | where EventID in (4688, 4663) and ProcessName has_any ("mimikatz", "procdump", "lsass") | summarize cred_time=min(TimeGenerated) by TargetUserName, Computer;
rdp_events | join kind=inner cred_events on TargetUserName, Computer | where cred_time - rdp_time between (0min .. 60min)

let smb_events = SecurityEvent | where EventID == 5140 and ShareName contains "\\" | summarize smb_time=min(TimeGenerated) by TargetUserName, Computer;
let lsa_events = SecurityEvent | where EventID == 4663 and ObjectName has_any ("lsa", "lsa secrets") | summarize lsa_time=min(TimeGenerated) by TargetUserName, Computer;
smb_events | join kind=inner lsa_events on TargetUserName | where lsa_time - smb_time between (0min .. 120min)

let ssh_events = Syslog | where Facility == "auth" and SyslogMessage contains "Accepted" and SyslogMessage contains "ssh" | summarize ssh_time=min(TimeGenerated), ssh_src=any(extract(@"from ([0-9.]+)", 1, SyslogMessage)) by TargetUserName, Computer;
let privesc_events = Syslog | where SyslogMessage has_any ("sudo", "su root", "uid=0") | summarize privesc_time=min(TimeGenerated) by TargetUserName, Computer;
ssh_events | join kind=inner privesc_events on TargetUserName, Computer | where privesc_time - ssh_time between (0min .. 60min)

let winrm_events = SecurityEvent | where EventID == 4624 and AuthenticationPackageName == "Negotiate" and ProcessName has "winrm" | summarize winrm_time=min(TimeGenerated) by TargetUserName, Computer;
let ps_events = SecurityEvent | where EventID == 4103 and ScriptBlockText has_any ("Get-ADDomainController", "Get-ADUser", "Invoke-Command") | summarize ps_time=min(TimeGenerated) by TargetUserName, Computer;
winrm_events | join kind=inner ps_events on TargetUserName | where ps_time - winrm_time between (0min .. 30min)

let wmi_events = SecurityEvent | where EventID == 4624 and ProcessName has "wmiprvse" | summarize wmi_time=min(TimeGenerated) by TargetUserName, Computer;
let schtask_events = SecurityEvent | where EventID == 4698 and TaskName !startswith "\\Microsoft" | summarize schtask_time=min(TimeGenerated) by SubjectUserName, Computer;
wmi_events | join kind=inner schtask_events on $left.TargetUserName == $right.SubjectUserName | where schtask_time - wmi_time between (0min .. 60min)

let dcom_events = SecurityEvent | where EventID == 4624 and AuthenticationPackageName == "Negotiate" and ProcessName has_any ("dcom", "rpcss") | summarize dcom_time=min(TimeGenerated) by TargetUserName, Computer;
let shell_events = SecurityEvent | where EventID == 4688 and NewProcessName has_any ("cmd.exe", "powershell.exe", "wscript.exe") | summarize shell_time=min(TimeGenerated) by SubjectUserName, Computer;
let c2_events = NetworkEvents | where RemoteUrl has_any ("pastebin", "github", "cloudflare") or DestinationPort in (4444, 8888, 9999) | summarize c2_time=min(TimeGenerated) by Computer;
dcom_events | join kind=inner shell_events on $left.TargetUserName == $right.SubjectUserName | where shell_time - dcom_time between (0min .. 30min)

let pth_events = SecurityEvent | where EventID == 4624 and AuthenticationPackageName == "NTLM" and LogonType == 3 | summarize pth_time=min(TimeGenerated) by TargetUserName, Computer;
let smb_events = SecurityEvent | where EventID == 5140 | summarize smb_time=min(TimeGenerated) by TargetUserName, Computer;
let da_events = SecurityEvent | where EventID == 4624 and TargetUserName endswith "-admin" or TargetUserName in ("Domain Admins", "Enterprise Admins") | summarize da_time=min(TimeGenerated) by TargetUserName;
pth_events | join kind=inner smb_events on TargetUserName | where smb_time - pth_time between (0min .. 60min)

let kerb_events = SecurityEvent | where EventID == 4769 and ServiceName !startswith "krbtgt" and TicketEncryptionType == "0x17" | summarize kerb_time=min(TimeGenerated) by ClientUserName, ServiceName;
let service_events = SecurityEvent | where EventID == 4624 and TargetUserName endswith "$" and LogonType == 3 | summarize svc_time=min(TimeGenerated) by TargetUserName;
kerb_events | join kind=inner service_events on $left.ServiceName == $right.TargetUserName | where svc_time - kerb_time between (0min .. 120min)

let phish_events = EmailEvents | where ThreatTypes has "Phish" | summarize phish_time=min(TimeGenerated) by RecipientEmailAddress;
let cred_events = SigninLogs | where ResultType == 0 and TimeGenerated > ago(24h) and ClientAppUsed has_any ("Exchange ActiveSync", "IMAP") | summarize cred_time=min(TimeGenerated) by UserPrincipalName;
phish_events | join kind=inner cred_events on $left.RecipientEmailAddress == $right.UserPrincipalName | where cred_time - phish_time between (0min .. 1440min)

let supply_events = SecurityEvent | where EventID == 4688 and ParentProcessName has_any ("update.exe", "installer.exe", "setup.exe") and ProcessName has_any ("powershell", "cmd", "wscript") | summarize supply_time=min(TimeGenerated) by Computer;
let pivot_events = SecurityEvent | where EventID == 4624 and LogonType == 3 | summarize pivot_time=min(TimeGenerated) by TargetUserName, Computer;
let staging_events = SecurityEvent | where EventID == 4663 and ObjectName has_any ("temp", "staging", "export") | summarize stage_time=min(TimeGenerated) by SubjectUserName;
supply_events | join kind=inner pivot_events on Computer | where pivot_time - supply_time between (0min .. 120min)

let exploit_events = SecurityEvent | where EventID == 4688 and NewProcessName has_any ("mshta.exe", "wmic.exe", "certutil.exe") | summarize exploit_time=min(TimeGenerated) by Computer;
let shell_events = SecurityEvent | where EventID == 4624 and LogonType == 10 | summarize shell_time=min(TimeGenerated) by Computer;
let propagation_events = NetworkEvents | where RemotePort in (445, 3389, 22, 135) | summarize prop_time=min(TimeGenerated), dest_count=dcount(DestinationIP) by SourceIP | where dest_count > 5;
exploit_events | join kind=inner shell_events on Computer | where shell_time - exploit_time between (0min .. 30min)

let vpn_events = SigninLogs | where AppDisplayName has_any ("VPN", "GlobalProtect", "AnyConnect") and ResultType == 0 | summarize vpn_time=min(TimeGenerated) by UserPrincipalName, IpAddress;
let recon_events = SecurityEvent | where EventID in (4662, 5136) | summarize recon_time=min(TimeGenerated) by SubjectUserName;
let lateral_events = SecurityEvent | where EventID == 4624 and LogonType == 3 | summarize lat_time=min(TimeGenerated) by TargetUserName;
vpn_events | join kind=inner recon_events on $left.UserPrincipalName == $right.SubjectUserName | where recon_time - vpn_time between (0min .. 60min)

let dns_events = DnsEvents | where QueryType in ("TXT", "NULL") and QueryName has_any ("data", "tunnel") | summarize dns_time=min(TimeGenerated), query_count=count() by ClientIP | where query_count > 50;
let exfil_events = NetworkEvents | where BytesSent > 1000000 and DestinationPort == 53 | summarize exfil_time=min(TimeGenerated) by SourceIP;
dns_events | join kind=inner exfil_events on $left.ClientIP == $right.SourceIP | where exfil_time - dns_time between (0min .. 60min)

let svc_events = SecurityEvent | where EventID == 4624 and TargetUserName endswith "$" and LogonType == 3 | summarize svc_time=min(TimeGenerated) by TargetUserName, Computer;
let schtask_events = SecurityEvent | where EventID == 4698 | summarize schtask_time=min(TimeGenerated) by SubjectUserName, Computer;
svc_events | join kind=inner schtask_events on $left.TargetUserName == $right.SubjectUserName, Computer | where schtask_time - svc_time between (0min .. 120min)

let reg_events = SecurityEvent | where EventID == 4657 and ObjectName has_any ("SAM", "SYSTEM", "SECURITY") | summarize reg_time=min(TimeGenerated) by SubjectUserName, Computer;
let cred_events = SecurityEvent | where EventID == 4663 and ObjectName has "lsass" | summarize cred_time=min(TimeGenerated) by SubjectUserName, Computer;
let golden_events = SecurityEvent | where EventID == 4768 and TicketEncryptionType == "0x17" | summarize golden_time=min(TimeGenerated) by TargetUserName;
reg_events | join kind=inner cred_events on SubjectUserName, Computer | where cred_time - reg_time between (0min .. 120min)

let api_events = AzureActivity | where OperationNameValue has_any ("Microsoft.Compute/virtualMachines/write", "Microsoft.ContainerInstance/containerGroups/write") and ActivityStatusValue == "Success" | summarize api_time=min(TimeGenerated) by Caller, ResourceGroup;
let cpu_events = Perf | where ObjectName == "Processor" and CounterName == "% Processor Time" | summarize avg_cpu=avg(CounterValue) by Computer, bin(TimeGenerated, 5m) | where avg_cpu > 95;
api_events | join kind=inner cpu_events on $left.ResourceGroup == $right.Computer | where cpu_events_TimeGenerated - api_time between (0min .. 120min)

let email_events = EmailEvents | where ThreatTypes has "Macro" or AttachmentExtension in ("xlsm", "docm", "xlsb") | summarize email_time=min(TimeGenerated) by RecipientEmailAddress;
let ps_events = SecurityEvent | where EventID == 4103 and ScriptBlockText has_any ("Invoke-WebRequest", "Invoke-Expression", "DownloadString") | summarize ps_time=min(TimeGenerated) by TargetUserName;
let exfil_events = NetworkEvents | where BytesSent > 5000000 | summarize exfil_time=min(TimeGenerated) by SourceIP;
email_events | join kind=inner ps_events on $left.RecipientEmailAddress == $right.TargetUserName | where ps_time - email_time between (0min .. 120min)

let exploit_events = SecurityEvent | where EventID == 4688 and NewProcessName has_any ("mshta.exe", "certutil.exe", "bitsadmin.exe") and ParentProcessName !has_any ("explorer.exe", "task scheduler") | summarize exploit_time=min(TimeGenerated) by Computer;
let enum_events = SecurityEvent | where EventID in (4662, 5136) and Properties has_any ("Domain Admins", "Enterprise Admins", "DNS") | summarize enum_time=min(TimeGenerated) by SubjectUserName;
exploit_events | join kind=inner enum_events on $left.Computer == $right.Computer | where enum_time - exploit_time between (0min .. 60min)

let container_events = KubeAuditLogs | where OperationName has_any ("exec", "attach", "port-forward") and StatusCode == "Success" | summarize container_time=min(TimeGenerated) by User, Namespace;
let metadata_events = NetworkEvents | where DestinationIP in ("169.254.169.254", "fd00:ec2::254") | summarize metadata_time=min(TimeGenerated) by SourceIP;
let iam_events = AzureActivity | where OperationNameValue has_any ("Microsoft.Authorization/roleAssignments/write", "Microsoft.Authorization/roleDefinitions/write") | summarize iam_time=min(TimeGenerated) by Caller;
container_events | join kind=inner metadata_events on $left.User == $right.SourceIP | where metadata_time - container_time between (0min .. 60min)

let iot_events = SecurityEvent | where Computer startswith "iot-" or ProcessName has_any ("firmware", "sensor", "gateway") and EventID == 4624 | summarize iot_time=min(TimeGenerated) by Computer;
let pivot_events = SecurityEvent | where EventID == 4624 and LogonType == 3 | summarize pivot_time=min(TimeGenerated) by TargetUserName, Computer;
iot_events | join kind=inner pivot_events on Computer | where pivot_time - iot_time between (0min .. 120min)

let cert_events = SecurityEvent | where EventID == 4624 and AuthenticationProtocol == "X509" | summarize cert_time=min(TimeGenerated) by TargetUserName, Computer;
let adcs_events = SecurityEvent | where EventID == 4898 or (EventID == 4662 and Properties has "Certificate Templates") | summarize adcs_time=min(TimeGenerated) by SubjectUserName;
cert_events | join kind=inner adcs_events on $left.TargetUserName == $right.SubjectUserName | where adcs_time - cert_time between (0min .. 120min)

let bf_events = SigninLogs | where ResultType == 50126 | summarize bf_count=count(), bf_time=min(TimeGenerated) by UserPrincipalName, IpAddress | where bf_count > 10;
let takeover_events = SigninLogs | where ResultType == 0 and TimeGenerated > ago(1h) | summarize takeover_time=min(TimeGenerated) by UserPrincipalName, IpAddress;
bf_events | join kind=inner takeover_events on UserPrincipalName | where takeover_time - bf_time between (0min .. 60min)

let admin_events = SecurityEvent | where EventID == 4688 and NewProcessName has_any ("procdump.exe", "mimikatz.exe", "lazagne.exe", "sharpkatz.exe") | summarize admin_time=min(TimeGenerated) by SubjectUserName, Computer;
let cred_events = SecurityEvent | where EventID == 4663 and ObjectName has "lsass" | summarize cred_time=min(TimeGenerated) by SubjectUserName, Computer;
let spread_events = SecurityEvent | where EventID == 4624 and LogonType == 3 | summarize spread_time=min(TimeGenerated), host_count=dcount(Computer) by TargetUserName | where host_count > 3;
admin_events | join kind=inner cred_events on SubjectUserName, Computer | where cred_time - admin_time between (0min .. 30min)

let storage_events = AzureActivity | where OperationNameValue has "Microsoft.Storage/storageAccounts/listKeys" and ActivityStatusValue == "Success" | summarize storage_time=min(TimeGenerated) by Caller, ResourceGroup;
let key_events = KeyVaultLogs | where OperationName == "KeyGet" or OperationName == "SecretGet" | summarize key_time=min(TimeGenerated) by Identity;
let sub_events = AzureActivity | where OperationNameValue has "Microsoft.Subscription" and ActivityStatusValue == "Success" | summarize sub_time=min(TimeGenerated) by Caller;
storage_events | join kind=inner key_events on $left.Caller == $right.Identity | where key_time - storage_time between (0min .. 60min)

let supply_events = SecurityEvent | where EventID == 4688 and ProcessName has_any ("npm", "pip", "gradle", "maven") and ProcessCommandLine has_any ("-g", "install", "--force") | summarize supply_time=min(TimeGenerated) by Computer;
let build_events = SecurityEvent | where EventID == 4688 and ProcessName has_any ("msbuild.exe", "docker", "kubectl") | summarize build_time=min(TimeGenerated) by Computer;
let prod_events = SecurityEvent | where EventID == 4624 and Computer startswith "prod-" | summarize prod_time=min(TimeGenerated) by Computer;
supply_events | join kind=inner build_events on Computer | where build_time - supply_time between (0min .. 120min)
